#include <bits/stdc++.h>
using namespace std;

const int MAXN = 202, INF = 0x3f3f3f3f;

int flow[MAXN][MAXN], capacity[MAXN][MAXN], parent[MAXN], queue_bfs[MAXN], dist[MAXN];

int BFS_edmonds(int totalNodes, int src, int dst) {
    int head, tail, node, u, v;
    while (true) {
        memset(parent, -1, sizeof(parent));
        dist[src] = INF;
        head = tail = 0;
        queue_bfs[tail++] = src;
        while (head < tail && parent[dst] < 0) {
            node = queue_bfs[head++];
            for (u = 0; u < totalNodes; ++u) {
                if (parent[u] < 0 && (v = capacity[node][u] - flow[node][u]) > 0) {
                    parent[queue_bfs[tail++] = u] = node;
                    dist[u] = min(dist[node], v);
                }
            }
        }
        if (parent[dst] < 0) break;
        for (u = dst; u != src; u = parent[u]) {
            flow[parent[u]][u] += dist[dst];
            flow[u][parent[u]] -= dist[dst];
        }
    }
    int total = 0;
    for (u = 0; u < totalNodes; ++u) total += flow[src][u];
    return total;
}

char initial[11], target[11];
int Zr, Zc, offsets[4][2] = {{0,1},{0,-1},{1,0},{-1,0}};
int dists[101][101];
int N, T;
vector<int> rowsB, colsB;

void bfs_run(int r, int c, int* outDists, bool withCheck) {
    queue<pair<int,int>> Q;
    outDists[r*N + c] = 0;
    Q.emplace(r, c);
    while (!Q.empty()) {
        auto [x, y] = Q.front(); Q.pop();
        int idx = x*N + y;
        int curDist = outDists[idx];
        if (withCheck && (dists[Zr*N + Zc][idx] <= curDist || T <= curDist)) {
            if (dists[Zr*N + Zc][idx] < curDist || T < curDist) outDists[idx] = INF + 1;
            continue;
        }
        for (int k = 0; k < 4; ++k) {
            int nx = x + offsets[k][0], ny = y + offsets[k][1];
            if (nx < 0 || ny < 0 || nx == N || ny == N) continue;
            if (target[nx][ny] < '0' || target[nx][ny] > '9') continue;
            int nidx = nx*N + ny;
            if (outDists[nidx] != INF) continue;
            outDists[nidx] = curDist + 1;
            Q.emplace(nx, ny);
        }
    }
}

void setup() {
    for (int i = 0; i < N; ++i)
        for (int j = 0; j < N; ++j)
            if (target[i][j] >= '1' && target[i][j] <= '9') {
                rowsB.emplace_back(i);
                colsB.emplace_back(j);
                capacity[(i*N + j) + 2 + N*N][1] = target[i][j] - '0';
            }
    int zIdx = Zr*N + Zc;
    for (int i = 0; i < N; ++i)
        for (int j = 0; j < N; ++j)
            if (initial[i][j] >= '1' && initial[i][j] <= '9') {
                int idx = i*N + j;
                capacity[0][idx + 2] = initial[i][j] - '0';
                for (int k = 0; k < rowsB.size(); ++k) {
                    int ri = rowsB[k], ci = colsB[k];
                    int qi = ri*N + ci;
                    if (dists[idx][qi] < INF)
                        capacity[idx + 2][qi + 2 + N*N] = INF;
                }
            }
}

int main() {
    ios::sync_with_stdio(false);
    cin >> N >> T;
    memset(dists, 0x3f, sizeof(dists));
    for (int i = 0; i < N; ++i) cin >> initial[i];
    for (int i = 0; i < N; ++i) cin >> target[i];
    for (int i = 0; i < N; ++i)
        for (int j = 0; j < N; ++j)
            if (initial[i][j] == 'Z') Zr = i, Zc = j;
    bfs_run(Zr, Zc, dists[Zr*N + Zc], false);
    for (int i = 0; i < N; ++i)
        for (int j = 0; j < N; ++j)
            if (initial[i][j] >= '1' && initial[i][j] <= '9')
                bfs_run(i, j, dists[i*N + j], true);
    setup();
    cout << BFS_edmonds(2 + N*N + N*N, 0, 1) << '\n';
}
